## 详细设计（JavaScript/Canvas 版本）

### 1. 技术栈修正说明

- **游戏引擎**：原生 JavaScript (ES6+)，使用 `requestAnimationFrame` 实现游戏循环。
- **渲染**：HTML5 Canvas 2D Context (`ctx`)。
- **模块化**：使用 ES6 的 `class` 和模块 (`import/export`)。
- **输入处理**：`addEventListener` 监听键盘事件。
- **状态管理**：纯 JavaScript 对象和类实现状态机。

### 2. 核心类定义（JavaScript）

**GameEngine.js**
```javascript
import { GameStateManager, GameState } from './GameStateManager.js';
import { FoodManager } from './FoodManager.js';
import { EffectScheduler } from './EffectScheduler.js';
import { Snake } from './Snake.js';
import { Renderer } from './Renderer.js';
import { InputHandler } from './InputHandler.js';

export class GameEngine {
    constructor(config) {
        this.config = config;
        this.stateManager = new GameStateManager();
        this.foodManager = new FoodManager(config.gridWidth, config.gridHeight);
        this.effectScheduler = new EffectScheduler();
        this.snake = new Snake(config.initialLength, Math.floor(config.gridWidth / 2), Math.floor(config.gridHeight / 2));
        this.score = 0;
        this.baseTickRate = config.tickRate; // 每秒更新次数
        this.accumulatedTime = 0;
        this.lastTimestamp = 0;
        this.isRunning = true;

        // 初始化模块
        this.inputHandler = new InputHandler(this);
        this.renderer = new Renderer(config.canvasId, config.gridSize);

        // 生成初始食物
        const occupied = new Set(this.snake.body.map(segment => `${segment.x},${segment.y}`));
        this.currentFood = this.foodManager.spawnFood(occupied);

        // 绑定游戏循环
        this.gameLoop = this.gameLoop.bind(this);
    }

    start() {
        this.lastTimestamp = performance.now();
        requestAnimationFrame(this.gameLoop);
    }

    gameLoop(timestamp) {
        if (!this.isRunning) return;

        const deltaTime = (timestamp - this.lastTimestamp) / 1000; // 转换为秒
        this.lastTimestamp = timestamp;

        // 1. 处理输入（InputHandler已通过事件监听器更新状态）
        this.inputHandler.processEvents();

        // 2. 更新逻辑
        const currentState = this.stateManager.getCurrentState();
        if (currentState.stateType === GameState.PLAYING) {
            this.update(deltaTime);
        }

        // 3. 渲染
        this.render();

        // 4. 继续循环
        requestAnimationFrame(this.gameLoop);
    }

    update(deltaTime) {
        // 更新效果调度器
        this.effectScheduler.update();

        // 计算实际tickRate（应用加速/减速效果）
        const speedMultiplier = this.effectScheduler.getEffectMultiplier('tickRateMultiplier');
        const actualTickRate = this.baseTickRate * speedMultiplier;

        // 固定时间步长更新
        this.accumulatedTime += deltaTime;
        const updateInterval = 1.0 / actualTickRate;

        while (this.accumulatedTime >= updateInterval) {
            this.accumulatedTime -= updateInterval;

            // 移动蛇
            this.snake.move();

            // 碰撞检测
            const head = this.snake.body[0];

            // 撞墙检测
            if (head.x < 0 || head.x >= this.config.gridWidth || 
                head.y < 0 || head.y >= this.config.gridHeight) {
                this.stateManager.changeState(GameState.GAMEOVER);
                return;
            }

            // 撞自身检测
            for (let i = 1; i < this.snake.body.length; i++) {
                if (head.x === this.snake.body[i].x && head.y === this.snake.body[i].y) {
                    this.stateManager.changeState(GameState.GAMEOVER);
                    return;
                }
            }

            // 吃食物检测
            if (this.currentFood && 
                head.x === this.currentFood.x && head.y === this.currentFood.y) {
                const foodType = this.currentFood.type;
                const effect = this.foodManager.getFoodEffect(foodType);
                effect.execute(this);

                // 生成新食物
                const occupied = new Set(this.snake.body.map(segment => `${segment.x},${segment.y}`));
                this.currentFood = this.foodManager.spawnFood(occupied);
            }
        }
    }

    render() {
        const renderData = {
            state: this.stateManager.getCurrentState().stateType,
            snakeBody: this.snake.body,
            food: this.currentFood,
            score: this.score,
            activeEffects: this.effectScheduler.getActiveEffectsDisplay()
        };
        this.renderer.draw(renderData);
    }
}
```

