### 3. EffectScheduler 时效管理实现

**EffectScheduler.js**
```javascript
export class EffectScheduler {
    constructor() {
        this.activeEffects = new Map(); // key: effectType, value: {value: any, remainingFrames: number}
    }

    /**
     * 添加或刷新一个有时限的效果
     * @param {string} effectType - 效果类型，如 'tickRateMultiplier'
     * @param {any} effectValue - 效果值，如 0.7（加速乘数）
     * @param {number} durationFrames - 持续帧数
     */
    addEffect(effectType, effectValue, durationFrames) {
        this.activeEffects.set(effectType, {
            value: effectValue,
            remainingFrames: durationFrames
        });
    }

    /**
     * 每帧更新，减少剩余帧数并移除过期效果
     */
    update() {
        const expiredEffects = [];

        for (const [effectType, effect] of this.activeEffects.entries()) {
            effect.remainingFrames--;
            if (effect.remainingFrames <= 0) {
                expiredEffects.push(effectType);
            }
        }

        // 移除过期效果
        expiredEffects.forEach(effectType => {
            this.activeEffects.delete(effectType);
        });
    }

    /**
     * 获取指定类型效果的当前值
     * @param {string} effectType - 效果类型
     * @param {any} defaultValue - 默认值（当效果不存在时返回）
     * @returns {any} 效果当前值
     */
    getEffectValue(effectType, defaultValue = null) {
        const effect = this.activeEffects.get(effectType);
        return effect ? effect.value : defaultValue;
    }

    /**
     * 获取指定类型效果的乘数（用于tickRate等）
     * @param {string} effectType - 效果类型
     * @returns {number} 乘数值，默认1.0
     */
    getEffectMultiplier(effectType) {
        const effect = this.activeEffects.get(effectType);
        return effect ? effect.value : 1.0;
    }

    /**
     * 获取用于UI显示的活动效果列表
     * @returns {Array<{name: string, duration: number}>} 效果显示列表
     */
    getActiveEffectsDisplay() {
        const displayList = [];

        for (const [effectType, effect] of this.activeEffects.entries()) {
            let displayName;
            switch (effectType) {
                case 'tickRateMultiplier':
                    displayName = effect.value < 1.0 ? '加速' : '减速';
                    break;
                default:
                    displayName = effectType;
            }

            // 将帧数转换为秒（假设60FPS）
            const durationSeconds = (effect.remainingFrames / 60).toFixed(1);
            displayList.push({
                name: displayName,
                duration: durationSeconds
            });
        }

        return displayList;
    }
}
