export class FoodManager {
    // ...（之前的构造函数和配置保持不变）

    spawnFood(occupiedPositions) {
        // ...（之前的类型选择逻辑保持不变）

        // 3. 选择位置（智能位置选择算法）
        let selectedPos;
        if (occupiedPositions.size > 0) {
            // 获取蛇头位置（从occupiedPositions中解析）
            const headKey = Array.from(occupiedPositions)[0]; // 假设第一个是蛇头
            const [headX, headY] = headKey.split(',').map(Number);

            // 计算每个空闲位置到蛇头的曼哈顿距离
            const positionsWithDistance = freePositions.map(pos => ({
                x: pos.x,
                y: pos.y,
                distance: Math.abs(pos.x - headX) + Math.abs(pos.y - headY)
            }));

            // 按距离从大到小排序（远离蛇头）
            positionsWithDistance.sort((a, b) => b.distance - a.distance);

            // 选择距离较远的前25%位置之一（增强游戏性）
            const topQuarterCount = Math.max(1, Math.floor(positionsWithDistance.length * 0.25));
            const topQuarter = positionsWithDistance.slice(0, topQuarterCount);

            const randomIndex = Math.floor(Math.random() * topQuarter.length);
            selectedPos = topQuarter[randomIndex];
        } else {
            // 没有占用位置（游戏刚开始），随机选择
            const randomIndex = Math.floor(Math.random() * freePositions.length);
            selectedPos = freePositions[randomIndex];
        }

        // 4. 创建食物对象
        this.currentFood = {
            x: selectedPos.x,
            y: selectedPos.y,
            type: foodType,
            color: this.getFoodColor(foodType) // 根据类型返回颜色
        };

        return this.currentFood;
    }

    /**
     * 根据食物类型返回渲染颜色
     */
    getFoodColor(foodType) {
        const colors = {
            'normal': '#FF5252', // 红色
            'speed_up': '#4CAF50', // 绿色
            'slow_down': '#2196F3' // 蓝色
        };
        return colors[foodType] || '#FF5252';
    }

    /**
     * 获取食物对应的效果对象
     */
    getFoodEffect(foodType) {
        return this.foodEffects[foodType];
    }

    /**
     * 清除当前食物（当被吃掉时调用）
     */
    clearCurrentFood() {
        this.currentFood = null;
    }
}
