        this.canvas = document.getElementById(canvasId);
        this.ctx = this.canvas.getContext('2d');
        this.gridSize = gridSize;

        // 颜色配置
        this.colors = {
            background: '#1a1a2e',
            grid: '#16213e',
            snake: '#4ecca3',
            snakeHead: '#0f9b8e',
            text: '#eeeeee',
            menuBg: 'rgba(0, 0, 0, 0.8)',
            pauseOverlay: 'rgba(0, 0, 0, 0.5)'
        };

        // 食物颜色映射
        this.foodColors = {
            'normal': '#FF5252', // 红色
            'speed_up': '#4CAF50', // 绿色
            'slow_down': '#2196F3'  // 蓝色
        };
    }

    draw(renderData) {
        // 清空画布
        this.ctx.fillStyle = this.colors.background;
        this.ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);

        // 绘制网格
        this.drawGrid();

        // 根据游戏状态绘制不同内容
        switch (renderData.state) {
            case GameState.MENU:
                this.drawMenu();
                break;
            case GameState.PLAYING:
            case GameState.PAUSED:
                this.drawGame(renderData);
                if (renderData.state === GameState.PAUSED) {
                    this.drawPauseOverlay();
                }
                break;
            case GameState.GAMEOVER:
                this.drawGame(renderData);
                this.drawGameOver(renderData.score);
                break;
        }

        // 绘制分数和状态信息（始终显示）
        this.drawHUD(renderData.score, renderData.activeEffects);
    }

    drawGrid() {
        this.ctx.strokeStyle = this.colors.grid;
        this.ctx.lineWidth = 0.5;

        // 绘制垂直线
        for (let x = 0; x <= this.canvas.width; x += this.gridSize) {
            this.ctx.beginPath();
            this.ctx.moveTo(x, 0);
            this.ctx.lineTo(x, this.canvas.height);
            this.ctx.stroke();
        }

        // 绘制水平线
        for (let y = 0; y <= this.canvas.height; y += this.gridSize) {
            this.ctx.beginPath();
            this.ctx.moveTo(0, y);
            this.ctx.lineTo(this.canvas.width, y);
            this.ctx.stroke();
        }
    }

    drawGame(renderData) {
        // 绘制蛇
        if (renderData.snakeBody && renderData.snakeBody.length > 0) {
            // 绘制蛇身
            for (let i = 0; i < renderData.snakeBody.length; i++) {
                const segment = renderData.snakeBody[i];
                const isHead = i === 0;

                this.ctx.fillStyle = isHead ? this.colors.snakeHead : this.colors.snake;
                this.ctx.fillRect(
                    segment.x * this.gridSize,
                    segment.y * this.gridSize,
                    this.gridSize - 1,
                    this.gridSize - 1
                );

                // 蛇头特殊绘制（眼睛）
                if (isHead) {
