import { NormalFoodEffect, SpeedUpFoodEffect, SlowDownFoodEffect } from './FoodEffect.js';

export class FoodManager {
    // 配置参数 - 可调整以平衡游戏性
    static SPECIAL_FOOD_SPAWN_CHANCE = 0.2; // 20%概率生成特殊食物
    static MIN_SPAWN_INTERVAL = 10; // 吃掉食物后至少10帧才可能生成特殊食物

    constructor(gridWidth, gridHeight) {
        this.gridWidth = gridWidth;
        this.gridHeight = gridHeight;
        this.currentFood = null;
        this.framesSinceLastFood = 0;

        // 食物效果映射
        this.foodEffects = {
            'normal': new NormalFoodEffect(),
            'speed_up': new SpeedUpFoodEffect(),
            'slow_down': new SlowDownFoodEffect()
        };

        // 特殊食物类型及权重配置
        this.specialFoodTypes = ['speed_up', 'slow_down'];
        this.specialFoodWeights = [0.6, 0.4]; // 加速食物60%，减速食物40%

        // 验证权重总和为1
        const weightSum = this.specialFoodWeights.reduce((a, b) => a + b, 0);
        if (Math.abs(weightSum - 1.0) > 0.001) {
            console.warn('Special food weights do not sum to 1, normalizing...');
            this.normalizeWeights();
        }
    }

    normalizeWeights() {
        const sum = this.specialFoodWeights.reduce((a, b) => a + b, 0);
        this.specialFoodWeights = this.specialFoodWeights.map(w => w / sum);
    }

    spawnFood(occupiedPositions) {
        // 如果当前有食物，不生成新食物
        if (this.currentFood) {
            return this.currentFood;
        }

        this.framesSinceLastFood++;

        // 1. 决定食物类型（概率计算）
        let foodType = 'normal';

        // 检查是否满足生成特殊食物的条件
        const canSpawnSpecial = 
            this.framesSinceLastFood >= FoodManager.MIN_SPAWN_INTERVAL &&
            Math.random() < FoodManager.SPECIAL_FOOD_SPAWN_CHANCE;

        if (canSpawnSpecial) {
            // 根据权重随机选择特殊食物类型
            const rand = Math.random();
            let cumulativeWeight = 0;

            for (let i = 0; i < this.specialFoodTypes.length; i++) {
                cumulativeWeight += this.specialFoodWeights[i];
                if (rand < cumulativeWeight) {
                    foodType = this.specialFoodTypes[i];
                    break;
                }
            }

            this.framesSinceLastFood = 0; // 重置冷却计时器
            console.log(`Special food spawned: ${foodType}`);
        }

        // 2. 寻找所有空闲位置
        const freePositions = [];
        for (let x = 0; x < this.gridWidth; x++) {
            for (let y = 0; y < this.gridHeight; y++) {
                const key = `${x},${y}`;
                if (!occupiedPositions.has(key)) {
                    freePositions.push({x, y});
                }
            }
        }

        if (freePositions.length === 0) {
            console.warn('No free positions for food spawn');
            return null;
        }

        // 3. 智能位置选择算法
        let selectedPos;

        if (occupiedPositions.size > 0 && freePositions.length > 1) {
            // 获取蛇头位置
            const headKey = Array.from(occupiedPositions)[0];
            const [headX, headY] = headKey.split(',').map(Number);

            // 计算每个空闲位置到蛇头的曼哈顿距离
            const positionsWithDistance = freePositions.map(pos => ({
                x: pos.x,
                y: pos.y,
                distance: Math.abs(pos.x - headX) + Math.abs(pos.y - headY)
            }));

            // 按距离从大到小排序
            positionsWithDistance.sort((a, b) => b.distance - a.distance);

            // 选择策略：80%从远距离位置选择，20%完全随机
            const useSmartPosition = Math.random() < 0.8;
            if (useSmartPosition) {
                // 选择距离较远的前25%位置
                const topQuarterCount = Math.max(1, Math.floor(positionsWithDistance.length * 0.25));
                const topQuarter = positionsWithDistance.slice(0, topQuarterCount);
                const randomIndex = Math.floor(Math.random() * topQuarter.length);
                selectedPos = topQuarter[randomIndex];
            } else {
                // 完全随机选择
                const randomIndex = Math.floor(Math.random() * freePositions.length);
                selectedPos = freePositions[randomIndex];
            }
        } else {
            // 没有占用位置或只有一个空闲位置
            const randomIndex = Math.floor(Math.random() * freePositions.length);
            selectedPos = freePositions[randomIndex];
        }

        // 4. 创建食物对象
        this.currentFood = {
            x: selectedPos.x,
            y: selectedPos.y,
            type: foodType,
            color: this.getFoodColor(foodType),
            spawnTime: Date.now()
        };

        return this.currentFood;
    }

