            'speed_up': '#4CAF50', // 绿色
            'slow_down': '#2196F3' // 蓝色
        };
        return colors[foodType] || '#FF5252';
    }

    getFoodEffect(foodType) {
        const effect = this.foodEffects[foodType];
        if (!effect) {
            console.error(`No effect found for food type: ${foodType}`);
            return this.foodEffects.normal; // 降级为普通食物
        }
        return effect;
    }

    clearCurrentFood() {
        this.currentFood = null;
    }

    // 用于调试
    getStats() {
        return {
            framesSinceLastFood: this.framesSinceLastFood,
            currentFood: this.currentFood
        };
    }
