        this.keyState[key] = true;

        // 防止方向键滚动页面
        if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright', ' '].includes(key)) {
            event.preventDefault();
        }

        // 将事件传递给当前游戏状态处理
        const currentState = this.gameEngine.stateManager.getCurrentState();
        currentState.handleInput(this, event);
    }

